-- sql/035_records_related_objects.sql
-- ============================================================

-- 035_records_related_objects.sql
-- 为记录增加「涉及对象」字段，用于存储弱关联的公司名、人名、客户名等对象线索
-- 这些对象先于事项存在，可以在持续跟进后升级为正式事项

ALTER TABLE records ADD COLUMN IF NOT EXISTS related_objects text[] DEFAULT '{}';

-- 同时为 review_status 增加枚举说明（不修改约束，保留文档性注释）
-- 'unchecked': 新创建，AI 建议未确认
-- 'confirmed': 用户或高置信自动确认
-- 'corrected': 用户纠正了 AI 建议
-- 'disputed': 用户标记为不确定

COMMENT ON COLUMN records.related_objects IS
  '弱关联对象线索，存储记录中提到但未升级为正式 item 的公司名、人名、客户名等';

-- ============================================================
-- sql/036_user_rules_extend.sql
-- ============================================================

-- ============================================================
-- 036: 扩展 user_rules 表的规则类型与来源枚举
--
-- 新增：
--   rule_type: no_assign — 「不归类」标记，避免同类词反复被猜
--   source: user_confirm — 用户手动确认/否定后写入
--   source: preset       — 系统内置词典种子
-- ============================================================

-- 移除旧的 rule_type CHECK 约束，改为更宽松版本
ALTER TABLE user_rules
  DROP CONSTRAINT IF EXISTS user_rules_rule_type_check;

ALTER TABLE user_rules
  ADD CONSTRAINT user_rules_rule_type_check
  CHECK (rule_type IN (
    'item_mapping', 'sub_item_mapping', 'type_routing',
    'fuzzy_resolution', 'function_mapping', 'tool_mapping',
    'no_assign'
  ));

