-- ============================================================

-- 记录展示编号：YYYYMMDD + 4 位当日序号（如 202601020001）
ALTER TABLE records ADD COLUMN IF NOT EXISTS display_no TEXT NULL;

CREATE INDEX IF NOT EXISTS idx_records_user_display_no
  ON records(user_id, display_no)
  WHERE display_no IS NOT NULL;

COMMENT ON COLUMN records.display_no IS '用户可见记录编号，创建时按归属日分配';

-- ============================================================
-- sql/038_record_notes_array.sql
-- ============================================================

-- 多条笔记：JSON 数组
ALTER TABLE records
  ADD COLUMN IF NOT EXISTS notes JSONB NOT NULL DEFAULT '[]'::jsonb;

-- 回填旧随手记：原文进 raw_input，清空 content
UPDATE records
SET raw_input = content, content = ''
WHERE input_source = 'quick'
  AND (raw_input IS NULL OR trim(raw_input) = '')
  AND content IS NOT NULL
  AND trim(content) <> '';

UPDATE records
SET notes = jsonb_build_array(note)
WHERE (notes IS NULL OR notes = '[]'::jsonb)
  AND note IS NOT NULL
  AND trim(note) <> '';

